html代码：

```html
<!DOCTYPE html>
<html>
<head>
    <meta charset="utf-8">
    <title>甘特图简单样例</title>
    <!-- 引入echarts库 -->
    <script src="https://cdn.jsdelivr.net/npm/echarts@4.9.0/dist/echarts.min.js"></script>
    <style type="text/css">
        /* 让echarts容器自适应屏幕 */
        .chart-container {
            width: 100%;
            height: 500px;
        }
    </style>
</head>
<body>
<!-- 甘特图echarts容器 -->
<div id="chart-container" class="chart-container"></div>

<!-- 甘特图数据 -->
<script>
    var data = [
        {
            "name": "任务1",
            "start": "2022-05-01",
            "end": "2022-06-01"
        },
        {
            "name": "任务2",
            "start": "2022-06-01",
            "end": "2022-07-01"
        },
        {
            "name": "任务3",
            "start": "2022-07-01",
            "end": "2022-08-01"
        }
    ];

    // 渲染甘特图
    var chart = echarts.init(document.getElementById('chart-container'));
    chart.title = '甘特图简单样例';
    chart.option = {
        tooltip: {
            formatter: function (params) {
                return params.name + ' : ' + params.value[0] + '-' + params.value[1];
            }
        },
        grid: {
            height: '50%',
            width: '80%',
            left: '10%',
            top: '20%'
        },
        xAxis: {
            type: 'time'
        },
        yAxis: {
            data: ['任务1', '任务2', '任务3']
        },
        series: [{
            type: 'custom',
            renderItem: function (params, api) {
                var duration = api.value(1) - api.value(0);
                var rectShape = echarts.graphic.clipRectByRect({
                    x: api.coord(params.value[0])[0],
                    y: api.coord(params.value[1])[1] - 0.3,
                    width: api.size([duration, 0])[0],
                    height: 0.6
                }, {
                    x: api.coord([0, 0])[0],
                    y: api.coord([0, 1])[1] - 0.6,
                    width: api.size([24 * 60 * 60 * 1000, 0])[0],
                    height: api.size([0, 1])[1] + 0.6
                });

                return rectShape && {
                    type: 'rect',
                    shape: rectShape,
                    style: api.style()
                };
            },
            itemStyle: {
                normal: {
                    color: '#2f4554'
                }
            },
            encode: {
                x: [1, 2],
                y: 0,
                tooltip: [1, 2]
            },
            data: data
        }]
    };
    chart.setOption(chart.option);
</script>
</body>
</html>
```

